def _populate_formula_caches(xlsx_path, values):
    """Patch xl/worksheets/sheet1.xml cached formula <v> nodes in-place."""
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp_path = tmp.name
    try:
        with zipfile.ZipFile(xlsx_path, 'r') as zin, zipfile.ZipFile(tmp_path, 'w', zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)
                if item.filename == 'xl/worksheets/sheet1.xml':
                    xml = data.decode('utf-8')
                    for addr, value in values.items():
                        value_text = format(float(value), '.15g')
                        pattern = re.compile(r'(<c r="' + re.escape(addr) + r'"[^>]*>.*?<f[^>]*>.*?</f>)(?:<v>.*?</v>)?(.*?</c>)')
                        xml, count = pattern.subn(r'\g<1><v>' + value_text + r'</v>\g<2>', xml, count=1)
                        if count != 1:
                            raise RuntimeError(f'Could not populate cache for {addr}')
                    data = xml.encode('utf-8')
                zout.writestr(item, data)
        os.replace(tmp_path, xlsx_path)
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)


